// Map an investigation failure to a fixed, secret-free cause and reason. Raw
// error text is never forwarded: it can carry provider or repository content.
// An HTTP error from GitHub, described by status, method and endpoint path (no host, query or credentials).
function apiErrorReason(error) {
  const where = (() => {
    try {return new URL(error.request.url).pathname.replace(/^\/repos\//, '').slice(0, 120);} catch {return 'an unknown endpoint';}
  })();
  const method = String(error.request?.method ?? 'GET').toUpperCase();
  const detail = String(error.message ?? '').replaceAll('@', '').replace(/\s+/g, ' ').slice(0, 100);
  return `GitHub API request failed: HTTP ${error.status} ${method} ${where}${detail ? ` (${detail})` : ''}.`;

}

function classify(error) {
  if (error?.code === 'PROVIDER_KEY') return {cause: error.cause_code, reason: error.message};
  const provider = /^(Acceptance|Jev) provider unavailable: HTTP ([0-9]{3})$/.exec(error?.message ?? '');
  if (provider) {
    const rejected = ['401', '403'].includes(provider[2]);
    return {cause: rejected ? 'provider_rejected' : 'provider_unavailable',
      reason: `${provider[1]} provider ${rejected ? 'rejected the credential' : 'was unavailable'} (HTTP ${provider[2]}).`};
  }
  if (error?.code === 'CHUNKED_RECORD') return {cause: error.cause_code, reason: error.message};
  if (error?.code === 'RATE_LIMIT') return {cause: 'github_rate_limit', reason: `Held: GitHub API rate limit, will retry after ${new Date(error.resetAt).toISOString()}.`};
  // A raw rate-limit response that escaped the retrying wrapper is the same hold, never a crash.
  const asked = rateLimitDelay(error);
  if (asked !== null) {
    const reset = error.response?.headers?.['x-ratelimit-reset'];
    const at = reset === undefined ? Date.now() + Math.max(asked, 900000) : Number(reset) * 1000;
    return {cause: 'github_rate_limit', reason: `Held: GitHub API rate limit, will retry after ${new Date(at).toISOString()}.`};
  }
  if (Number.isInteger(error?.status) && error.status >= 400) return {cause: 'github_api_error', reason: apiErrorReason(error)};
  const message = error?.message ?? '';
  // Every known failure of the AI step maps to a fixed cause that names the missing or failing item.
  // Only our own constant messages (and a repository path) are forwarded, never provider or source text.
  if (error?.unavailable) return {cause: 'changed_file_unreadable', reason: `Changed file ${String(error.path ?? 'unknown').slice(0, 200)} cannot be read as complete text within the review limits (not found, binary, invalid text or over 300 KB).`};
  if (/^Acceptance provider returned an invalid structured result$|^Acceptance provider returned malformed JSON$/.test(message)) {
    return {cause: 'review_output_invalid', reason: 'The reviewer model returned an unusable answer (invalid tool call or malformed JSON) on 3 consecutive attempts with the same prompt.'};
  }
  if (message === 'Acceptance provider did not complete the bounded review') return {cause: 'provider_incomplete', reason: 'The reviewer model did not complete its answer within the bounded token budget.'};
  const invalid = /^Invalid acceptance evidence: (.*)$/.exec(message);
  if (invalid) {
    const detail = /^[a-z0-9 ,'-]{1,120}$/i.test(invalid[1]) ? `: ${invalid[1]}` : '';
    return {cause: 'review_output_invalid', reason: `The reviewer's output failed controller validation on 3 consecutive attempts${detail}.`};
  }
  if (/^(?:Technical finding|Unknown controller-supplied|Unit paths are derived)/.test(message)) return {cause: 'review_output_invalid', reason: 'The reviewer returned a finding or unit the controller cannot bind to the changed source, on 3 consecutive attempts.'};
  if (message === 'Complete review evidence exceeds the source budget') return {cause: 'evidence_budget', reason: 'The changed files together exceed the 900 KB review evidence budget.'};
  if (message === 'Changed-file evidence is incomplete') return {cause: 'changed_files_incomplete', reason: 'GitHub did not supply a complete patch for every changed file.'};
  if (message === 'Repository tree is too large to locate the existing tests') return {cause: 'tree_truncated', reason: 'The repository tree is too large to locate the existing tests.'};
  if (/^Automated source investigation exhausted/.test(message)) return {cause: 'investigation_exhausted', reason: 'The reviewer kept requesting source after its bounded investigation budget.'};
  return {cause: 'evidence_incomplete', reason: GENERIC};
}

function reviewDecision(record, {chunked = null} = {}) {
  const {snapshot, result} = record;
  const verifier = Object.hasOwn(record, 'partition') ? chunkedVerifier(record, chunked) : null;
  requireReceipt(snapshot && result && snapshot.digest === (verifier ? verifier.snapshotDigest() : refresh(structuredClone(snapshot)).digest),
    'altered evidence snapshot');
  requireReceipt(result.snapshot === snapshot.digest && result.policy_digest === snapshot.policy_digest &&
    result.config_digest === snapshot.config_digest, 'review does not match evidence');
  const graded = role => result.reviews?.find(item => item.role === role)?.report?.findings?.length > 0;
  requireReceipt(Array.isArray(result.usage) && result.usage.length >= 2 &&
    result.execution_digest === digest(result.usage) && new Set(result.usage.map(item => item.session)).size === result.usage.length &&
    result.usage.every(item => ['codex', 'claude', 'opencode'].includes(item.harness) && [undefined, 'agent_session'].includes(item.execution) &&
      typeof item.session === 'string' && item.session.length > 0 &&
      ['request_digest', 'response_digest', 'transport_digest'].every(name => /^[a-f0-9]{64}$/.test(item[name]))) &&
    // Grading runs only for findings, so a role without findings has no grading round to record.
    // A chunked record accounts for every unit and the integration pass inside its own verifier.
    (verifier || ['examiner', 'challenger'].every(role => ['investigation', 'grading'].every(phase =>
      (phase === 'grading' && !graded(role)) || result.usage.some(item => item.role === role && item.phase === phase)))),
    'complete independent harness execution records required');
  requireReceipt(Array.isArray(result.reviews) && result.reviews.length === 2 &&
    result.reviews.map(item => item.role).join(',') === 'examiner,challenger', 'two independent roles required');
  const reviews = verifier ? verifier.reviews() : result.reviews.map(item => ({...item,
    scores: validateReport(item.report, validateInspection(item.report, snapshot, item.drafts))}));
  const prior = record.local_previous?.findings || [];
  requireReceipt(digest(snapshot.prior_findings) === digest(prior), 'local finding history differs from the reviewed evidence');
  const state = reconcile({...result, reviews}, snapshot, prior);
  const combined = combine(reviews);
  const decision = state.unresolved.length && combined === 'auto_approve' ? 'review_incomplete' : combined;
  requireReceipt(result.decision === decision, 'claimed decision differs from calculated decision');
  return {decision, reviews};
}

function issueReceipt({record, privateKey, keyId, issuer, reviewerSha, reviewerDigest = engineDigest(), now = Date.now(), lifetime = 172800,
  nonce = crypto.randomBytes(32).toString('hex'), chunked = null}) {
  requireReceipt(reviewDecision(record, {chunked}).decision === 'auto_approve', 'only a passing review can be signed');
  requireReceipt(sha(reviewerSha) && /^[a-f0-9]{64}$/.test(reviewerDigest) && /^[a-f0-9]{64}$/.test(nonce) && Number.isSafeInteger(lifetime) &&
    lifetime > 0 && lifetime <= 172800, 'invalid runner revision, challenge or lifetime');
  const key = crypto.createPrivateKey(privateKey);
  requireReceipt(key.asymmetricKeyType === 'ed25519', 'Ed25519 signing key required');
  const payload = {type: DOMAIN, key_id: keyId, issuer, reviewer_sha: reviewerSha, reviewer_digest: reviewerDigest,
    issued_at: Math.floor(now / 1000), expires_at: Math.floor(now / 1000) + lifetime,

    nonce, record_digest: digest(record), record};
  const signature = crypto.sign(null, Buffer.from(`${DOMAIN}\0${digest(payload)}`), key).toString('base64url');
  return {payload, signature};
}

function verifySignedRecord(bundle, {trust, repository, author, headSha, baseSha, reviewerSha, reviewerDigest = engineDigest(), configDigest, policyDigest,
  now = Date.now(), engine = null, chunked = null}) {
  validateTrust(trust);
  requireReceipt(bundle && Object.keys(bundle).sort().join(',') === 'payload,signature' &&
    typeof bundle.signature === 'string' && /^[a-zA-Z0-9_-]{86}$/.test(bundle.signature) &&
    Buffer.byteLength(JSON.stringify(bundle)) <= MAX_RECEIPT_BYTES, 'malformed signature envelope');
  const p = bundle.payload;
  requireReceipt(p && Object.keys(p).sort().join(',') ===
    'expires_at,issued_at,issuer,key_id,nonce,record,record_digest,reviewer_digest,reviewer_sha,type' && p.type === DOMAIN,
    'unknown receipt type or fields');
  const key = trust.keys.find(item => item.id === p.key_id && item.issuer === p.issuer && !item.revoked);
  requireReceipt(key && crypto.verify(null, Buffer.from(`${DOMAIN}\0${digest(p)}`), key.public_key,
    Buffer.from(bundle.signature, 'base64url')), 'untrusted, revoked or invalid signature');
  requireReceipt(key.github_actor === author, 'signing identity is not enrolled for this PR author');
  const timestamp = Math.floor(now / 1000);
  requireReceipt(Number.isSafeInteger(p.issued_at) && Number.isSafeInteger(p.expires_at) &&
    p.issued_at <= timestamp && p.expires_at > timestamp && p.expires_at > p.issued_at &&
    p.expires_at - p.issued_at <= trust.max_age_seconds && timestamp - p.issued_at <= trust.max_age_seconds &&
    typeof p.nonce === 'string' && /^[a-f0-9]{64}$/.test(p.nonce), 'expired, future or invalid challenge');
  if (trust.central_source || engine) {
    requireReceipt(acceptsEngine(trust, engine) && engine.digest === reviewerDigest &&
      p.reviewer_digest === engine.digest && p.reviewer_sha === engine.sha,
    'engine mismatch; refresh public Clouseau and review again, then start a fresh CI run. No paid fallback is allowed');
  }
  const record = p.record;
  const snapshot = record.snapshot;
  requireReceipt(p.record_digest === digest(record) && snapshot.repository === repository &&
    sha(headSha) && snapshot.head_sha === headSha && sha(baseSha) && snapshot.base_sha === baseSha &&
    sha(p.reviewer_sha) && (!reviewerSha || p.reviewer_sha === reviewerSha) &&
    p.reviewer_digest === reviewerDigest && (engine || trust.reviewer_digest === reviewerDigest) && snapshot.config_digest === configDigest &&
    snapshot.policy_digest === policyDigest, 'repository, revisions, policy, configuration or record changed');
  const result = reviewDecision(record, {chunked});
  requireReceipt(result.decision === 'auto_approve', 'review did not pass');
  return {record, ...result};
}

'use strict';
// A local, deliberately simple stand-in for the partition and merge modules (which other changes own), written
// against the pinned contract only: one unit per changed path, unions for the merge, strictest gate wins.
const crypto = require('node:crypto');
const {CASES, prepareCase} = require('./acceptance-cases.cjs');
const {GATES, digest} = require('../src/acceptance.cjs');
const {modelTemplate, materialize} = require('../src/acceptance-review.cjs');
const {refresh} = require('../src/acceptance-sources.cjs');
const {elideQuotes} = require('../src/chunked-record.cjs');
const {FACTORS} = require('../src/acceptance.cjs');

const PARAMS = {C: 450000, S: 100000, cap: 2400000, max_units: 16};
const STRICT = ['violated', 'unresolved', 'satisfied', 'inapplicable'];

function unitView(snapshot, spec) {
  const other = snapshot.files.filter(file => !spec.owned.includes(file.path));
  const hidden = new Set(other.flatMap(file => [file.base_source, file.head_source]));
  const view = {...snapshot, paths: [...spec.owned], files: snapshot.files.filter(file => spec.owned.includes(file.path)),
    sources: Object.fromEntries(Object.entries(snapshot.sources).filter(([id]) => !hidden.has(id)))};
  return refresh(view);
}

function planOf(snapshot, params, groups) {
  const units = groups.map((owned, index) => {
    const spec = {id: `u${index}`, owned, context_ids: [], cost: 1};
    return {...spec, view_digest: unitView(snapshot, spec).digest};
  });
  const plan = {scheme: 'clouseau-partition/1', params: {C: params.C, S: params.S, cap: params.cap}, units};
  return {...plan, plan_digest: digest(plan)};
}

const hooks = {
  partition: ({snapshot, params}) => planOf(snapshot, params, [...snapshot.paths].sort().map(path => [path])),
  unitView,
  seams: () => [],
  merge({unitReports, snapshot}) {
    const prefix = (value, unit) => {
      if (Array.isArray(value)) return value.map(item => prefix(item, unit));
      if (!value || typeof value !== 'object') return value;
      return Object.fromEntries(Object.entries(value).map(([key, item]) => [key,

        key === 'evidence' && Array.isArray(item) && item.every(id => typeof id === 'string') ? item.map(id => `${unit}:${id}`) :
          key === 'id' ? `${unit}:${item}` :
            key === 'units' && item.every(id => typeof id === 'string') ? item.map(id => `${unit}:${id}`) : prefix(item, unit)]));
    };
    const parts = unitReports.map(({unit, report}) => prefix(report, unit));
    const sources = Object.keys(snapshot.sources).map(source => {
      const candidates = parts.flatMap(part => part.coverage.sources.filter(item => item.source === source));
      return candidates.find(item => item.state === 'missing') || candidates.find(item => item.state === 'inspected') || candidates[0];
    });
    return {version: 4, snapshot: snapshot.digest, summary: parts.map(part => part.summary).join(' '),
      evidence: parts.flatMap(part => part.evidence), units: parts.flatMap(part => part.units),
      findings: parts.flatMap(part => part.findings), accounting: parts.flatMap(part => part.accounting),
      resolutions: parts.flatMap(part => part.resolutions),
      gates: GATES.map(name => {
        const gates = parts.map(part => part.gates.find(gate => gate.name === name));
        return {name, state: STRICT.find(state => gates.some(gate => gate.state === state)), reason: gates[0].reason,
          evidence: gates.flatMap(gate => gate.evidence)};
      }),
      coverage: {sources, dependencies: parts.flatMap(part => part.coverage.dependencies)},
      reopenings: parts.flatMap(part => part.reopenings)};
  },
};

function unitReport(view, {finding = false} = {}) {
  const report = modelTemplate(view);
  report.gates.forEach(gate => {gate.state = 'satisfied';});
  const completed = materialize(report, view);
  if (finding) {
    const [evidence] = completed.accounting[0].evidence;
    completed.findings.push({id: 'fictional-defect', title: 'Fictional fixture defect', path: completed.accounting[0].path,
      cause: 'The changed path no longer preserves the accepted contract.', trigger: 'A fictional input.',
      consequence: 'A fictional regression.', obligation: 'Restore the accepted contract.', evidence: [evidence],
      factors: Object.fromEntries(FACTORS.defect.map(name => [name, {value: 0, evidence: [evidence], reason: 'Established by the cited source.'}])),
      blast_radius: 1, opportunity: {mechanical: false, beneficial: false, within_scope: false, verified: false},
      repair_paths: [completed.accounting[0].path]});
  }
  return completed;
}

async function chunkedFixture({params = PARAMS, groups, finding = false} = {}) {

  const {snapshot} = await prepareCase(CASES[1]);
  Object.assign(snapshot, {number: 0, prior_findings: []}); refresh(snapshot);
  const plan = groups ? planOf(snapshot, params, groups) : hooks.partition({snapshot, params});
  const views = plan.units.map(unit => unitView(snapshot, unit));
  const usage = []; let calls = 0;
  const call = (role, phase, unit) => {
    calls++;
    const entry = {harness: 'codex', role, phase, session: `fictional-session-${calls}`, ...(unit ? {unit} : {}),
      request_digest: digest(['request', calls]), response_digest: digest(['response', calls]), transport_digest: digest(['transport', calls])};
    usage.push(entry);
  };
  const reviews = ['examiner', 'challenger'].map(role => {
    const full = plan.units.map((unit, index) => ({unit: unit.id, report: unitReport(views[index], {finding: finding && index === 0})}));
    for (const unit of plan.units) call(role, 'investigation', unit.id);
    call(role, 'integration');
    const merged = hooks.merge({unitReports: full, snapshot});
    const {locations, grade} = require('../src/acceptance-grading.cjs');
    const decisions = locations(merged).map(entry => ({id: entry.id, provider: 'local-harness', answer: 'level0', value: grade('level0').value}));
    if (decisions.length) call(role, 'grading');
    return {role, unit_reports: full.map((item, index) => ({unit: item.unit, report: elideQuotes(item.report, views[index])})),
      integration: [], drafts: [], grading: {provider: 'local-harness', decisions}};
  });
  const result = {version: 2, snapshot: snapshot.digest, policy_digest: snapshot.policy_digest, config_digest: snapshot.config_digest,
    decision: 'auto_approve', reviews, usage, execution_digest: digest(usage)};
  const record = {version: 3, snapshot, partition: plan, seams: [], result, previous: {comment: null, findings: []},
    controls: false, technical: JSON.parse(snapshot.sources.verification.content)};
  const keys = crypto.generateKeyPairSync('ed25519');
  const trust = {mode: 'required', reviewer_digest: require('../src/local-version.cjs').engineDigest(), max_age_seconds: 172800,
    keys: [{id: 'test-runner', issuer: 'fictional-runner', github_actor: 'fixture-author', revoked: false,
      public_key: keys.publicKey.export({type: 'spki', format: 'pem'})}]};
  const chunked = {params, hooks};
  return {snapshot, record, plan, views, chunked, trust, params,
    issue: {record, privateKey: keys.privateKey.export({type: 'pkcs8', format: 'pem'}), keyId: 'test-runner', issuer: 'fictional-runner',
      reviewerSha: 'e'.repeat(40), now: 10000000, nonce: 'f'.repeat(64), chunked},
    expected: {trust, repository: snapshot.repository, author: 'fixture-author', headSha: snapshot.head_sha, baseSha: snapshot.base_sha,
      reviewerSha: 'e'.repeat(40), configDigest: snapshot.config_digest, policyDigest: snapshot.policy_digest, now: 10000000, chunked}};
}

module.exports = {chunkedFixture, hooks, unitView, planOf, PARAMS};

function parseParams(raw) {
  const keys = ['C', 'S', 'cap', 'max_units'];
  if (!raw || typeof raw !== 'object' || Object.keys(raw).sort().join(',') !== [...keys].sort().join(',') ||
      !keys.every(key => positive(raw[key])) || raw.cap > MAX_RECEIPT_BYTES) {
    invalid('protected chunk parameters {C, S, cap, max_units} must be positive integers within the receipt bound');
  }
  return {C: raw.C, S: raw.S, cap: raw.cap, max_units: raw.max_units};
}
const planParams = ({C, S, cap}) => ({C, S, cap});

function snapshotDigest(snapshot, cap) {
  const value = {...snapshot}; delete value.digest;
  need(JSON.stringify(value).length <= cap, 'combined evidence exceeds the protected snapshot cap');
  return digest(value);
}

function assertRecordSize(record, limit = RECORD_LIMIT) {
  const bytes = Buffer.byteLength(JSON.stringify(record));
  if (bytes > limit) {
    throw new ChunkedRecordError('record_too_large',
      `record_too_large: the record is ${bytes} bytes, above the ${limit} byte signing limit of the ${MAX_RECEIPT_BYTES} byte receipt`);
  }
  return bytes;
}

const regenerated = (entry, snapshot) => snapshot.sources[entry.source].content.split('\n').slice(entry.start - 1, entry.end).join('\n');
const citation = (entry, snapshot) => entry && typeof entry.id === 'string' && Object.hasOwn(snapshot.sources, entry.source) &&
  Number.isSafeInteger(entry.start) && Number.isSafeInteger(entry.end) && entry.start >= 1 && entry.end >= entry.start &&
  entry.end <= snapshot.sources[entry.source].content.split('\n').length;

// Store thin: a quote the controller can regenerate byte for byte from source and coordinates is dropped.
// Anything else (a shorter quote, a forged one) is kept so that validation still sees it.
function elideQuotes(report, snapshot) {
  const thin = structuredClone(report);
  thin.evidence = thin.evidence.map(entry => {
    if (!citation(entry, snapshot) || entry.quote !== regenerated(entry, snapshot)) return entry;
    const {quote, ...reference} = entry;
    return reference;
  });
  return thin;

}

// The exact inverse. A thin entry takes the regenerated quote; an entry that still has one keeps it for validation.
function rehydrateQuotes(report, snapshot) {
  need(Array.isArray(report?.evidence), 'report has no evidence register');
  const full = structuredClone(report);
  full.evidence = full.evidence.map(entry => {
    need(citation(entry, snapshot), `evidence entry ${named(entry?.id)} cites no known source lines`);
    if (Object.hasOwn(entry, 'quote')) return entry;
    need(Object.keys(entry).sort().join(',') === 'end,id,source,start', `thin evidence entry ${named(entry.id)} has unexpected fields`);
    return {...entry, quote: regenerated(entry, snapshot)};
  });
  return full;
}

// Wrap the existing validators so their (controller-constant) messages become a visible, specific reason.
function checked(subject, run) {
  try {return run();} catch (error) {
    return invalid(`${subject} failed validation: ${String(error.message).slice(0, 160)}`);
  }
}

function checkOwnership(snapshot, plan) {
  const owner = new Map(); const ids = new Set();
  for (const unit of plan.units) {
    need(unit && typeof unit.id === 'string' && !ids.has(unit.id), `unit id ${named(unit?.id)} is missing or repeated`);
    ids.add(unit.id);
    need(Array.isArray(unit.owned) && unit.owned.length > 0 && Array.isArray(unit.context_ids), `unit ${unit.id} has no owned paths`);
    for (const path of unit.owned) {
      need(snapshot.paths.includes(path), `unit ${unit.id} owns ${named(path)}, which is not a changed path`);
      need(!owner.has(path), `duplicate ownership: ${named(path)} is owned by units ${owner.get(path)} and ${unit.id}`);
      owner.set(path, unit.id);
    }
    need(new Set(unit.context_ids).size === unit.context_ids.length &&
      unit.context_ids.every(id => Object.hasOwn(snapshot.sources, id)), `unit ${unit.id} lists unknown or repeated context sources`);
  }
  const unowned = snapshot.paths.filter(path => !owner.has(path));
  need(unowned.length === 0, `changed path ${named(unowned[0])} is owned by no unit`);
}

      const reviews = result.reviews.map(review => {
        const role = review.role;
        need(!Object.hasOwn(review, 'report') && !Object.hasOwn(review, 'scores'),
          `${role} review stores a merged report or scores; the merged report is derived and must not be stored`);
        need(Array.isArray(review.integration), `${role} has no integration entries`);
        const unitReports = unitReportsOf(review, partition, views, role);
        const merged = hooks.merge({role, unitReports, integration: review.integration, snapshot, plan: partition});
        graded[role] = applyGrades(merged, review, role);
        const drafts = (review.drafts ?? []).map(draft => rehydrateQuotes(draft, snapshot));
        const scores = checked(`${role} merged report`, () => validateReport(merged, validateInspection(merged, snapshot, drafts)));
        return {role, report: merged, drafts, scores};
      });
      checkUsage(result, partition, graded);
      return reviews;
    },
  };
}

module.exports = {SCHEME, RECORD_LIMIT, ChunkedRecordError, parseParams, snapshotDigest, assertRecordSize, elideQuotes, rehydrateQuotes, chunkedVerifier};

});

